package com.cowave.search.domain.dictionary

import com.fasterxml.jackson.annotation.JsonIgnoreProperties
import java.time.Instant

@JsonIgnoreProperties(ignoreUnknown = true)
class Dictionary(
    val id: String?,
    val keyword: String?,
    val type: Type,
    val value: String?,
    val createdTime: Instant,
    val updatedTime: Instant,
) {
    companion object {
        fun of(
            keyword: String?,
            type: Type,
            value: String?,
            createdTime: Instant,
            updatedTime: Instant,
        ): Dictionary =
            Dictionary(
                null,
                keyword = keyword,
                type = type,
                value = value,
                createdTime = createdTime,
                updatedTime = updatedTime,
            )
    }
}
